/**
 * ChartForge — Task 18 演示种子（成品 PNG 装饰素材）
 *
 * 用法：打开 dev server 后访问
 *   http://localhost:5174/?demo=t18#/workbench/t18-png-demo
 * 即会写入一块**已经摆好**的演示屏：
 *   紫曜光轨边框（整屏）+ 紫曜铭牌标题框 + 冰蓝玻璃面板框 + 霓虹星簇角饰 + 碳纤刻度块，
 * 底下是真实的图表 / 指标卡 / 地图，看得出 PNG 素材叠在数据之上是什么观感。
 *
 * 想自己动手：
 *   1. 左侧「设计库」→ 滚到底部「内置装饰」，右上角带 PN G 角标的 11 个就是 T18 新增的成品位图；
 *   2. 四种分类筛选里都有 PNG（大屏边框 4 / 标题框 2 / 背景框 2 / 装饰素材 3）；
 *   3. 点卡片或直接拖到画布都能插入，插入后可撤销、可收藏；
 *   4. T17 的 23 个矢量装饰原样保留，两条路混着用不冲突。
 *
 * 注意：本文件里的 PNG 数据 URL 与 src/assets/decor-png/ 同源，
 * 由 scripts/sync-decor-png.mjs 生成的 decorPng.ts 摘录而来，仅用于演示。
 */
(() => {
  const STORAGE_KEY = "chartforge.workspace.v1";
  const SCREEN_ID = "t18-png-demo";
  const DATASET_ID = "t18-demo-regions";
  const PNG = {
  "border-violet": "data:image/png;base64,",
  "title-violet": "data:image/png;base64,",
  "panel-azure": "data:image/png;base64,",
  "orn-stars": "data:image/png;base64,",
  "orn-ticks": "data:image/png;base64,"
};

  const regions = [
    { province: "广东省", score: 92 }, { province: "江苏省", score: 84 },
    { province: "浙江省", score: 78 }, { province: "山东省", score: 71 },
    { province: "湖北省", score: 63 }, { province: "湖南省", score: 58 },
    { province: "四川省", score: 55 }, { province: "云南省", score: 49 },
    { province: "新疆维吾尔自治区", score: 41 },
    { province: "黑龙江省", score: 36 }, { province: "内蒙古自治区", score: 33 },
    { province: "西藏自治区", score: 28 },
  ];
  const channels = [
    { name: "线上直播", value: 86 }, { name: "私域运营", value: 72 },
    { name: "线下门店", value: 64 }, { name: "经销商", value: 93 },
  ];

  const decor = (id, asset, name, frame) => ({
    id, name, kind: "image", src: PNG[asset], fit: "fill", opacity: 1,
    frame: { ...frame, rotate: 0 },
  });

  const items = [
    // ── PNG 装饰（压在最底层，先入数组）────────────────────────────
    decor("t18-border", "border-violet", "紫曜光轨边框", { x: 0, y: 0, w: 1600, h: 900 }),
    decor("t18-title", "title-violet", "紫曜铭牌标题框", { x: 250, y: 34, w: 1100, h: 68 }),
    decor("t18-panel", "panel-azure", "冰蓝玻璃面板框", { x: 1020, y: 400, w: 520, h: 300 }),
    decor("t18-stars", "orn-stars", "霓虹星簇角饰", { x: 62, y: 44, w: 144, h: 125 }),
    decor("t18-ticks", "orn-ticks", "碳纤刻度块", { x: 1380, y: 128, w: 175, h: 80 }),

    // ── 真实内容 ─────────────────────────────────────────────────
    {
      id: "t18-kpi", name: "指标卡", kind: "component",
      componentId: "chartforge.kpi", componentVersion: 1,
      frame: { x: 120, y: 170, w: 300, h: 150, rotate: 0 },
      props: { valueField: "value", label: "本月营收", format: "currency", aggregation: "sum" },
      dataBinding: { datasetId: DATASET_ID, fields: { value: "value" } },
    },
    {
      id: "t18-progress", name: "进度条组", kind: "component",
      componentId: "chartforge.progress-list", componentVersion: 1,
      frame: { x: 1080, y: 430, w: 400, h: 220, rotate: 0 },
      props: { labelField: "name", valueField: "value", maxValue: 100, fillColor: "", trackColor: "" },
      dataBinding: { datasetId: DATASET_ID, fields: { name: "name", value: "value" } },
    },
    {
      id: "t18-map", name: "平面地图", kind: "component",
      componentId: "chartforge.map-scene-flat", componentVersion: 1,
      frame: { x: 120, y: 360, w: 620, h: 460, rotate: 0 },
      props: {
        presentation: "flat", pitch: 0, backgroundColor: "#100a1c",
        border: { color: "#c9a6ff", width: 1, type: "solid" },
        label: { show: true, color: "#f2eaff", size: 10, stroke: "#2a1146" },
        legend: { show: true, position: "top-right", mode: "continuous" },
        layers: [{
          id: "t18-fill", type: "regionFill", name: "省级热度", visible: true,
          style: {
            color: "#b07cff", opacity: 0.85, size: 12, colorMode: "gradient",
            colors: { min: "#1a1030", mid: "#5b2fa8", max: "#c79bff", empty: "#150d26" },
          },
        }],
      },
      dataBinding: { datasetId: DATASET_ID, fields: { province: "province", value: "score" } },
    },
  ];

  const screen = {
    id: SCREEN_ID,
    name: "PNG 装饰演示",
    themeId: "monitor-dark",
    canvas: { width: 1600, height: 900, background: { kind: "color", color: "#0a0f16" } },
    items,
    updatedAt: Date.now(),
  };

  const existing = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "null");
  const workspace =
    existing && typeof existing === "object"
      ? existing
      : { version: 2, assets: [], designAssets: [], screens: [], datasets: [], settings: { autosave: true } };
  workspace.favorites = [
    { kind: "decor", id: "decor-png-border-violet" },
    { kind: "decor", id: "decor-png-panel-azure" },
    { kind: "component", id: "chartforge.kpi", version: 1 },
  ];
  workspace.screens = (workspace.screens ?? []).filter((entry) => entry?.id !== SCREEN_ID);
  workspace.screens.push(screen);
  workspace.datasets = (workspace.datasets ?? []).filter((entry) => entry?.id !== DATASET_ID);
  workspace.datasets.push({
    id: DATASET_ID,
    name: "区域销售（PNG 演示）",
    source: {
      kind: "static",
      data: regions.map((row, index) => ({ ...row, name: channels[index % channels.length].name, value: channels[index % channels.length].value })),
    },
    pipeline: { filter: [] },
  });
  localStorage.setItem(STORAGE_KEY, JSON.stringify(workspace));
  console.log("[chartforge] T18 PNG 装饰演示屏已写入：#/workbench/t18-png-demo");
})();
